// Second, independent exhaustive search (different algorithm from subsp.c), prime fields.
// Question: does the multiplication tensor of A = F_q[x]/(f), deg f = n <= 4, q prime,
// have rank <= n + 4 over F_q?
// Method: rank <= n+4 iff exists W >= S (S = slice span, dim n) of dim n+4 spanned by
// rank-one matrices; W = S + <F1,F2,F3,F4>, Fi rank-one with independent images in the
// quotient V = F_q^{n^2}/S.  F1 is reduced to one representative per orbit of the
// symmetry group generated by M -> L_u^T M L_v (u, v units of A) and M -> M^T; F2 < F3
// range over all pairs; F4 is handled by bucketing all rank-ones by their projective image
// modulo Q3 = <F1,F2,F3> (each bucket = one 4-dim subspace Q4 containing Q3).
// Usage: bucket q c0 c1 ... cn   (coefficients of monic f, low to high)
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAXN 4
#define D (MAXN * MAXN)
static int q, n, nn, dq;          // dq = quotient dimension nn - n
static int inv[16];
static int Sb[MAXN][D], piv[MAXN];
static int nonp[D];
static int nr;
static int (*R1)[D];      // rank-one matrices (projective reps)
static int (*IM)[D];      // images in quotient (length dq)
static int *fa, *fb;      // functional indices for each rank-one
static int nfun;
static int (*FUN)[MAXN];

static int md(int x) { x %= q; return x < 0 ? x + q : x; }

static void normalize(int *v, int len) {
  for (int i = 0; i < len; i++) if (v[i]) { int s = inv[v[i]]; for (int j = i; j < len; j++) v[j] = v[j] * s % q; return; }
}

static int Mbuf[4096][D];
static int rank_rows(int rows[][D], int k, int len) {
  int (*M)[D] = Mbuf; memcpy(M, rows, sizeof(int) * D * k);
  int r = 0;
  for (int c = 0; c < len && r < k; c++) {
    int p = -1;
    for (int i = r; i < k; i++) if (M[i][c]) { p = i; break; }
    if (p < 0) continue;
    if (p != r) for (int j = 0; j < len; j++) { int t = M[p][j]; M[p][j] = M[r][j]; M[r][j] = t; }
    int s = inv[M[r][c]];
    for (int j = 0; j < len; j++) M[r][j] = M[r][j] * s % q;
    for (int i = 0; i < k; i++) if (i != r && M[i][c]) { int f = M[i][c]; for (int j = 0; j < len; j++) M[i][j] = md(M[i][j] - f * M[r][j]); }
    r++;
  }
  return r;
}

// multiplication in A: polynomials mod f
static int fc[MAXN + 1];
static void mulA(const int *x, const int *y, int *z) {
  int t[2 * MAXN] = {0};
  for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) t[i + j] = (t[i + j] + x[i] * y[j]) % q;
  for (int d = 2 * n - 2; d >= n; d--) if (t[d]) { int c = t[d]; for (int k = 0; k <= n; k++) t[d - n + k] = md(t[d - n + k] - c * fc[k]); }
  for (int i = 0; i < n; i++) z[i] = t[i];
}

int main(int argc, char **argv) {
  q = atoi(argv[1]); n = argc - 3; nn = n * n;
  for (int i = 0; i <= n; i++) fc[i] = md(atoi(argv[2 + i]));
  for (int a = 1; a < q; a++) for (int b = 1; b < q; b++) if (a * b % q == 1) inv[a] = b;
  // slices: S_k[i*n+j] = coefficient of x^k in x^i * x^j
  int sl[MAXN][D]; memset(sl, 0, sizeof sl);
  for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
    int x[MAXN] = {0}, y[MAXN] = {0}, z[MAXN]; x[i] = 1; y[j] = 1; mulA(x, y, z);
    for (int k = 0; k < n; k++) sl[k][i * n + j] = z[k];
  }
  // reduced row echelon of S
  memcpy(Sb, sl, sizeof sl);
  { int r = 0;
    for (int c = 0; c < nn && r < n; c++) {
      int p = -1; for (int i = r; i < n; i++) if (Sb[i][c]) { p = i; break; }
      if (p < 0) continue;
      for (int j = 0; j < nn; j++) { int t = Sb[p][j]; Sb[p][j] = Sb[r][j]; Sb[r][j] = t; }
      int s = inv[Sb[r][c]]; for (int j = 0; j < nn; j++) Sb[r][j] = Sb[r][j] * s % q;
      for (int i = 0; i < n; i++) if (i != r && Sb[i][c]) { int f = Sb[i][c]; for (int j = 0; j < nn; j++) Sb[i][j] = md(Sb[i][j] - f * Sb[r][j]); }
      piv[r++] = c;
    }
    if (r != n) { printf("slices dependent\n"); return 1; }
  }
  dq = 0;
  for (int c = 0; c < nn; c++) { int isp = 0; for (int i = 0; i < n; i++) if (piv[i] == c) isp = 1; if (!isp) nonp[dq++] = c; }
  // projective functionals
  int qn = 1; for (int i = 0; i < n; i++) qn *= q;
  FUN = malloc(sizeof(int) * MAXN * qn); nfun = 0;
  for (int code = 1; code < qn; code++) {
    int v[MAXN], c = code; for (int i = 0; i < n; i++) { v[i] = c % q; c /= q; }
    int first = 0; for (int i = 0; i < n; i++) if (v[i]) { first = v[i]; break; }
    if (first != 1) continue;
    memcpy(FUN[nfun++], v, sizeof(int) * MAXN);
  }
  nr = nfun * nfun;
  R1 = malloc(sizeof(int) * D * nr); IM = malloc(sizeof(int) * D * nr);
  fa = malloc(sizeof(int) * nr); fb = malloc(sizeof(int) * nr);
  int t = 0;
  for (int a = 0; a < nfun; a++) for (int b = 0; b < nfun; b++, t++) {
    fa[t] = a; fb[t] = b;
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) R1[t][i * n + j] = FUN[a][i] * FUN[b][j] % q;
    int v[D]; memcpy(v, R1[t], sizeof v);
    for (int r = 0; r < n; r++) if (v[piv[r]]) { int f = v[piv[r]]; for (int j = 0; j < nn; j++) v[j] = md(v[j] - f * Sb[r][j]); }
    for (int k = 0; k < dq; k++) IM[t][k] = v[nonp[k]];
  }
  // orbits of functionals under phi -> phi o L_u, u a unit
  int *cls = malloc(sizeof(int) * nfun); for (int i = 0; i < nfun; i++) cls[i] = -1;
  int ncls = 0;
  int units[4096][MAXN], nu = 0;
  for (int code = 1; code < qn; code++) {
    int u[MAXN], c = code; for (int i = 0; i < n; i++) { u[i] = c % q; c /= q; }
    int L[MAXN][D]; // columns: u * x^j
    int rows[MAXN][D]; memset(rows, 0, sizeof rows);
    for (int j = 0; j < n; j++) { int e[MAXN] = {0}, z[MAXN]; e[j] = 1; mulA(u, e, z); for (int i = 0; i < n; i++) rows[j][i] = z[i]; }
    (void)L;
    if (rank_rows(rows, n, n) == n) { memcpy(units[nu++], u, sizeof(int) * MAXN); }
  }
  for (int s = 0; s < nfun; s++) if (cls[s] < 0) {
    int stack[4096], sp = 0; stack[sp++] = s; cls[s] = ncls;
    while (sp) {
      int a = stack[--sp];
      for (int k = 0; k < nu; k++) {
        // (phi o L_u)(x^j) = phi(u x^j)
        int w[MAXN];
        for (int j = 0; j < n; j++) { int e[MAXN] = {0}, z[MAXN]; e[j] = 1; mulA(units[k], e, z); int acc = 0; for (int i = 0; i < n; i++) acc += FUN[a][i] * z[i]; w[j] = acc % q; }
        normalize(w, n);
        int idx = -1; for (int g = 0; g < nfun; g++) if (!memcmp(FUN[g], w, sizeof(int) * n)) { idx = g; break; }
        if (cls[idx] < 0) { cls[idx] = ncls; stack[sp++] = idx; }
      }
    }
    ncls++;
  }
  printf("q=%d n=%d units=%d proj functionals=%d classes=%d rank-ones=%d quotient dim=%d\n", q, n, nu, nfun, ncls, nr, dq);
  // representatives of rank-one orbits: unordered class pairs
  int reps[64], nreps = 0;
  for (int c1 = 0; c1 < ncls; c1++) for (int c2 = c1; c2 < ncls; c2++)
    for (int s = 0; s < nr; s++) if (cls[fa[s]] == c1 && cls[fb[s]] == c2) { reps[nreps++] = s; break; }
  printf("F1 representatives: %d\n", nreps);
  int qd = 1; for (int i = 0; i < dq; i++) qd *= q;
  int *cnt = calloc(qd, sizeof(int)); int *touched = malloc(sizeof(int) * nr); int *key = malloc(sizeof(int) * nr);
  int (*R2)[D] = malloc(sizeof(int) * D * nr);
  long long triples = 0, cand = 0, hits = 0;
  for (int ri = 0; ri < nreps; ri++) {
    int F1 = reps[ri];
    for (int F2 = 0; F2 < nr; F2++) {
      if (F2 == F1) continue;
      // echelon basis E of <img F1, img F2>
      int E[2][D]; int ep[2];
      memcpy(E[0], IM[F1], sizeof(int) * D); normalize(E[0], dq);
      ep[0] = -1; for (int k = 0; k < dq; k++) if (E[0][k]) { ep[0] = k; break; }
      if (ep[0] < 0) continue;
      memcpy(E[1], IM[F2], sizeof(int) * D);
      if (E[1][ep[0]]) { int f = E[1][ep[0]]; for (int k = 0; k < dq; k++) E[1][k] = md(E[1][k] - f * E[0][k]); }
      normalize(E[1], dq);
      ep[1] = -1; for (int k = 0; k < dq; k++) if (E[1][k]) { ep[1] = k; break; }
      if (ep[1] < 0) continue;
      if (E[0][ep[1]]) { int f = E[0][ep[1]]; for (int k = 0; k < dq; k++) E[0][k] = md(E[0][k] - f * E[1][k]); }
      for (int s = 0; s < nr; s++) {
        int *v = R2[s]; memcpy(v, IM[s], sizeof(int) * D);
        for (int e = 0; e < 2; e++) if (v[ep[e]]) { int f = v[ep[e]]; for (int k = 0; k < dq; k++) v[k] = md(v[k] - f * E[e][k]); }
      }
      for (int F3 = F2 + 1; F3 < nr; F3++) {
        if (F3 == F1) continue;
        int p3 = -1; for (int k = 0; k < dq; k++) if (R2[F3][k]) { p3 = k; break; }
        if (p3 < 0) continue;
        triples++;
        int w3[D]; memcpy(w3, R2[F3], sizeof(int) * D); normalize(w3, dq);
        static int common[4096]; int nc = 0, nt = 0;
        for (int s = 0; s < nr; s++) {
          int v[D]; memcpy(v, R2[s], sizeof(int) * dq);
          if (v[p3]) { int f = v[p3]; for (int k = 0; k < dq; k++) v[k] = md(v[k] - f * w3[k]); }
          int nz = 0; for (int k = 0; k < dq; k++) if (v[k]) { nz = 1; break; }
          if (!nz) { common[nc++] = s; key[s] = -1; continue; }
          normalize(v, dq);
          int kk = 0; for (int k = dq - 1; k >= 0; k--) kk = kk * q + v[k];
          key[s] = kk;
          if (cnt[kk]++ == 0) touched[nt++] = kk;
        }
        // rank of the rank-ones lying in W3 = S + <F1,F2,F3>; a bucket can only complete
        // W (dim n+4) if it has at least n+4-r3 elements
        static int crow[4096][D];
        for (int c = 0; c < nc; c++) memcpy(crow[c], R1[common[c]], sizeof(int) * D);
        int r3 = rank_rows(crow, nc, nn);
        for (int s = 0; s < nr; s++) {
          if (key[s] < 0) continue;
          int kk = key[s];
          if (cnt[kk] >= n + 4 - r3 && cnt[kk] > 0) {
            cand++;
            static int rows[4096][D]; int k = 0;
            for (int c = 0; c < nc; c++) memcpy(rows[k++], R1[common[c]], sizeof(int) * D);
            for (int s2 = 0; s2 < nr; s2++) if (key[s2] == kk) memcpy(rows[k++], R1[s2], sizeof(int) * D);
            int rk = rank_rows(rows, k, nn);
            if (rk == n + 4) {
              hits++;
              if (hits <= 3) printf("HIT F1=%d F2=%d F3=%d bucket size %d common %d\n", F1, F2, F3, cnt[kk], nc);
              if (getenv("DUMP")) {
                FILE *fo = fopen(getenv("DUMP"), "w");
                for (int c = 0; c < nc; c++) { for (int i = 0; i < n; i++) fprintf(fo, "%d ", FUN[fa[common[c]]][i]); for (int j = 0; j < n; j++) fprintf(fo, "%d ", FUN[fb[common[c]]][j]); fprintf(fo, "\n"); }
                for (int s2 = 0; s2 < nr; s2++) if (key[s2] == kk) { for (int i = 0; i < n; i++) fprintf(fo, "%d ", FUN[fa[s2]][i]); for (int j = 0; j < n; j++) fprintf(fo, "%d ", FUN[fb[s2]][j]); fprintf(fo, "\n"); }
                fclose(fo); printf("dumped W rank-ones to %s\n", getenv("DUMP")); exit(0);
              }
            }
            cnt[kk] = -1000000; // mark bucket processed
          }
        }
        for (int i = 0; i < nt; i++) cnt[touched[i]] = 0;
      }
      if (F2 % 100 == 0) { fprintf(stderr, "rep %d/%d F2 %d/%d triples %lld cand %lld hits %lld\n", ri + 1, nreps, F2, nr, triples, cand, hits); fflush(stderr); }
    }
  }
  printf("RESULT q=%d f=", q); for (int i = 0; i <= n; i++) printf("%d%s", fc[i], i < n ? "," : "");
  printf(" rank<=%d: %s (triples %lld, candidate buckets %lld, hits %lld)\n", n + 4, hits ? "YES" : "NO", triples, cand, hits);
  return 0;
}
